# Rebuild molecule, set heavy coords from embed, re-add Hs
from rdkit import Chem
from rdkit.Chem import rdDistGeom
import numpy as np, json

# parse heavy atoms from initial_v2_clean.xyz
lines = open('initial_v2_clean.xyz').read().splitlines()
atoms=[l.split() for l in lines[2:]]
heavy = atoms[:57]
hv = np.array([[float(v) for v in a[1:]] for a in heavy])

# rebuild mol
mol = Chem.RWMol(); idx={}
def add(el,key):
    i=mol.AddAtom(Chem.Atom(el)); idx[key]=i; return i
for r in range(1,4):
    for k in range(6): add('C',f'R{r}_{k}')
for n in range(1,5): add('N',f'N{n}')
add('C','Carm1'); add('C','Carm4')
for p in range(1,4): add('P',f'P{p}')
for g in range(6):
    add('C',f'iPr{g}_CH'); add('C',f'iPr{g}_Me1'); add('C',f'iPr{g}_Me2')
add('Co','Co1'); add('Co','Co2')
add('N','N5'); add('N','N6')
for s in range(1,3):
    add('Si',f'Si{s}')
    for m in range(3): add('C',f'Si{s}_Me{m}')
def bond(k1,k2,bt=Chem.BondType.SINGLE): mol.AddBond(idx[k1],idx[k2],bt)
for r in range(1,4):
    for k in range(6):
        bond(f'R{r}_{k}',f'R{r}_{(k+1)%6}',Chem.BondType.AROMATIC)
        mol.GetAtomWithIdx(idx[f'R{r}_{k}']).SetIsAromatic(True)
bond('R1_0','N1'); bond('R1_1','N2')
bond('R2_0','N2'); bond('R2_1','N3')
bond('R3_0','N3'); bond('R3_1','N4')
bond('N1','Carm1'); bond('Carm1','P1')
bond('N4','Carm4'); bond('Carm4','P2')
bond('N3','P3')
for p,gs in zip([1,2,3],[(0,1),(2,3),(4,5)]):
    for g in gs:
        bond(f'P{p}',f'iPr{g}_CH'); bond(f'iPr{g}_CH',f'iPr{g}_Me1'); bond(f'iPr{g}_CH',f'iPr{g}_Me2')
for n in range(1,5): bond('Co1',f'N{n}')
for p in range(1,4): bond('Co2',f'P{p}')
bond('Co2','N4'); bond('Co2','N5',Chem.BondType.DOUBLE)
bond('N5','N6'); bond('N6','Si1'); bond('N6','Si2')
for s in range(1,3):
    for m in range(3): bond(f'Si{s}',f'Si{s}_Me{m}')
mol=mol.GetMol()
Chem.SanitizeMol(mol,Chem.SanitizeFlags.SANITIZE_NONE)

conf = Chem.Conformer(57)
for i in range(57):
    conf.SetAtomPosition(i, hv[i].tolist())
mol.RemoveAllConformers()
mol.AddConformer(conf)

molH = Chem.AddHs(mol, addCoords=True)
# check for zero H
c = molH.GetConformer()
bad=[]
for a in molH.GetAtoms():
    if a.GetSymbol()=='H':
        p=c.GetAtomPosition(a.GetIdx())
        if abs(p.x)<1e-6 and abs(p.y)<1e-6 and abs(p.z)<1e-6:
            bad.append(a.GetIdx())
print('H at origin after re-add:', len(bad))
print('total:', molH.GetNumAtoms())
if bad:
    # place those H manually: for each bad H, its neighbor heavy atom; place tetrahedrally
    import numpy as np
    pos = np.array([[c.GetAtomPosition(i).x, c.GetAtomPosition(i).y, c.GetAtomPosition(i).z] for i in range(molH.GetNumAtoms())])
    def tetra_H(center_idx, bond_len=1.09):
        # neighbor atoms of center (heavy only)
        nb = [a.GetIdx() for a in molH.GetAtomWithIdx(center_idx).GetNeighbors() if molH.GetAtomWithIdx(a.GetIdx()).GetSymbol()!='H']
        vec = np.zeros(3)
        for j in nb:
            v = pos[center_idx]-pos[j]
            vec += v/np.linalg.norm(v)
        vec = vec/np.linalg.norm(vec)
        return pos[center_idx] + vec*bond_len
    for hidx in bad:
        center = molH.GetAtomWithIdx(hidx).GetNeighbors()[0].GetIdx()
        newp = tetra_H(center)
        c.SetAtomPosition(hidx, newp.tolist())
Chem.MolToXYZFile(molH, 'initial_v3.xyz')
print('written initial_v3.xyz')
