from rdkit import Chem
from rdkit.Chem import rdDistGeom
import numpy as np, json

mol = Chem.RWMol(); idx={}
def add(el,key):
    i=mol.AddAtom(Chem.Atom(el)); idx[key]=i; return i
for r in range(1,4):
    for k in range(6): add('C',f'R{r}_{k}')
for n in range(1,5): add('N',f'N{n}')
add('C','Carm1'); add('C','Carm4')
for p in range(1,4): add('P',f'P{p}')
for g in range(6):
    add('C',f'iPr{g}_CH'); add('C',f'iPr{g}_Me1'); add('C',f'iPr{g}_Me2')
add('Co','Co1'); add('Co','Co2')
add('N','N5'); add('N','N6')
for s in range(1,3):
    add('Si',f'Si{s}')
    for m in range(3): add('C',f'Si{s}_Me{m}')
def bond(k1,k2,bt=Chem.BondType.SINGLE): mol.AddBond(idx[k1],idx[k2],bt)
for r in range(1,4):
    for k in range(6):
        bond(f'R{r}_{k}',f'R{r}_{(k+1)%6}',Chem.BondType.AROMATIC)
        mol.GetAtomWithIdx(idx[f'R{r}_{k}']).SetIsAromatic(True)
bond('R1_0','N1'); bond('R1_1','N2')
bond('R2_0','N2'); bond('R2_1','N3')
bond('R3_0','N3'); bond('R3_1','N4')
bond('N1','Carm1'); bond('Carm1','P1')
bond('N4','Carm4'); bond('Carm4','P2')
bond('N3','P3')
for p,gs in zip([1,2,3],[(0,1),(2,3),(4,5)]):
    for g in gs:
        bond(f'P{p}',f'iPr{g}_CH'); bond(f'iPr{g}_CH',f'iPr{g}_Me1'); bond(f'iPr{g}_CH',f'iPr{g}_Me2')
for n in range(1,5): bond('Co1',f'N{n}')
for p in range(1,4): bond('Co2',f'P{p}')
bond('Co2','N4'); bond('Co2','N5',Chem.BondType.DOUBLE)
bond('N5','N6'); bond('N6','Si1'); bond('N6','Si2')
for s in range(1,3):
    for m in range(3): bond(f'Si{s}',f'Si{s}_Me{m}')
mol=mol.GetMol()
Chem.SanitizeMol(mol,Chem.SanitizeFlags.SANITIZE_NONE)
json.dump(idx, open('idx_v5.json','w'))

# bonded pairs set (to exclude from clash count)
bonded=set()
for b in mol.GetBonds():
    i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
    bonded.add((min(i,j),max(i,j)))

Co1,Co2=idx['Co1'],idx['Co2']
donors=[idx[k] for k in ['N1','N2','N3','N4']]
Pd=[idx[k] for k in ['P1','P2','P3']]

def score(mol):
    c=mol.GetConformer()
    pos=np.array([[c.GetAtomPosition(i).x,c.GetAtomPosition(i).y,c.GetAtomPosition(i).z] for i in range(mol.GetNumAtoms())])
    clash=0
    n=len(pos)
    for i in range(n):
        for j in range(i+1,n):
            if (i,j) in bonded: continue
            d=np.linalg.norm(pos[i]-pos[j])
            if d<1.15: clash+=1
    # donor-metal distances target range
    pen=0.0
    for d_ in donors:
        dd=np.linalg.norm(pos[Co1]-pos[d_])
        pen += abs(dd-2.0)
    for d_ in Pd:
        dd=np.linalg.norm(pos[Co2]-pos[d_])
        pen += abs(dd-2.3)
    dd=np.linalg.norm(pos[Co2]-pos[idx['N4']])
    pen += abs(dd-2.05)
    return clash, pen

best=None
for seed in range(1,25):
    ps=rdDistGeom.ETKDGv3()
    ps.randomSeed=seed
    ps.useRandomCoords=True
    ps.maxIterations=800
    ok=rdDistGeom.EmbedMolecule(mol,ps)
    if ok!=0: 
        continue
    clash,pen=score(mol)
    print(f'seed {seed}: clash {clash} pen {pen:.2f}')
    if best is None or (clash,pen)<best[0]:
        best=((clash,pen),seed,Chem.Mol(mol))
print('BEST seed', best[1], 'score', best[0])
m=best[2]
Chem.MolToXYZFile(m,'heavy_best.xyz')
